package io.asv.odinlab;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import android.content.Intent;import android.graphics.*;import java.io.*;import java.util.concurrent.*;import org.json.*;
import com.google.mlkit.vision.documentscanner.*;
/** Google supplied document flow, not a detector inside our CameraX preview. */
public class DocumentLabActivity extends Activity {
 private TextView status;private ImageView preview;private Button start;private boolean busy,pendingExternal;private long began;private Bitmap shown;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){began=state.getLong("began");pendingExternal=state.getBoolean("pendingExternal");busy=pendingExternal;}LinearLayout col=new LinearLayout(this);col.setOrientation(LinearLayout.VERTICAL);col.setPadding(24,32,24,24);TextView title=new TextView(this);title.setText("ML Kit Document Scanner · LAB\ncodex/dinov2-benchmark");col.addView(title);status=new TextView(this);status.setText("Prueba manual independiente. Google Play services descarga el módulo la primera vez. Procesado on-device; no es CameraX ni detector multitarjeta. Devuelve un JPEG corregido. Sin filtros de mejora. No modifica la colección.");col.addView(status);start=new Button(this);start.setText("Escanear documento/carta con ML Kit");col.addView(start);preview=new ImageView(this);preview.setAdjustViewBounds(true);col.addView(preview);ScrollView scroll=new ScrollView(this);scroll.addView(col);setContentView(scroll);start.setEnabled(!busy);start.setOnClickListener(v->launch());}
 private void launch(){if(busy)return;busy=true;start.setEnabled(false);began=android.os.SystemClock.elapsedRealtime();status.setText("Preparando flujo ML Kit (puede descargar módulo)…");GmsDocumentScannerOptions options=new GmsDocumentScannerOptions.Builder().setGalleryImportAllowed(true).setPageLimit(1).setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG).setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_BASE).build();GmsDocumentScanning.getClient(options).getStartScanIntent(this).addOnSuccessListener(sender->{if(isFinishing()||isDestroyed())return;try{pendingExternal=true;startIntentSenderForResult(sender,72,null,0,0,0);}catch(Exception e){failed(e);}}).addOnFailureListener(this::failed);}
 private void failed(Exception e){if(isDestroyed())return;pendingExternal=false;busy=false;start.setEnabled(true);status.setText("ML Kit no disponible: "+e);}
 @Override protected void onActivityResult(int request,int code,Intent data){super.onActivityResult(request,code,data);if(request!=72)return;pendingExternal=false;if(code!=RESULT_OK){busy=false;start.setEnabled(true);status.setText("Cancelado; no se ha guardado ninguna carta.");return;}GmsDocumentScanningResult result=GmsDocumentScanningResult.fromActivityResultIntent(data);if(result==null||result.getPages()==null||result.getPages().isEmpty()){failed(new IOException("Sin JPEG"));return;}android.net.Uri uri=result.getPages().get(0).getImageUri();long workflow=android.os.SystemClock.elapsedRealtime()-began;status.setText("Comparando JPEG corregido con Milo y Diego…");worker.execute(()->{Bitmap image=null;try{File dir=new File(getFilesDir(),"mlkit-document-"+System.currentTimeMillis());if(!dir.mkdirs())throw new IOException("mkdir");try(InputStream in=getContentResolver().openInputStream(uri)){java.nio.file.Files.copy(in,new File(dir,"document.jpg").toPath());}String imagePath=new File(dir,"document.jpg").toString();BitmapFactory.Options decode=new BitmapFactory.Options();decode.inJustDecodeBounds=true;BitmapFactory.decodeFile(imagePath,decode);decode.inSampleSize=1;while(Math.max(decode.outWidth,decode.outHeight)/decode.inSampleSize>4096)decode.inSampleSize*=2;decode.inJustDecodeBounds=false;image=BitmapFactory.decodeFile(imagePath,decode);if(image==null)throw new IOException("JPEG");if(Math.max(image.getWidth(),image.getHeight())>2048){double ratio=2048.0/Math.max(image.getWidth(),image.getHeight());Bitmap resized=Bitmap.createScaledBitmap(image,(int)(image.getWidth()*ratio),(int)(image.getHeight()*ratio),true);image.recycle();image=resized;}JSONObject report=new JSONObject().put("scope","Google document UI output; workflow time includes user interaction and is NOT inference latency").put("workflow_ms",workflow);try(LiveEngine engine=new LiveEngine(getApplicationContext())){report.put("milo",engine.identify(image,true)).put("diego",engine.identify(image,false));}CaptureEngine.save(dir,"results.json",report);Bitmap show=image;image=null;runOnUiThread(()->{if(isDestroyed()){show.recycle();return;}if(shown!=null)shown.recycle();shown=show;preview.setImageBitmap(show);busy=false;start.setEnabled(true);try{status.setText("Guardado aparte: "+dir.getName()+"\nMilo: "+report.getJSONObject("milo").getJSONArray("top").getJSONObject(0).getString("label")+"\nDiego: "+report.getJSONObject("diego").getJSONArray("top").getJSONObject(0).getString("label")+"\nRevisa bordes; similitud no confirma acierto.");}catch(Exception e){failed(e);}});}catch(Exception e){runOnUiThread(()->failed(e));}finally{if(image!=null)image.recycle();}});}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putLong("began",began);state.putBoolean("pendingExternal",pendingExternal);}
 @Override protected void onDestroy(){worker.shutdown();if(shown!=null){preview.setImageDrawable(null);shown.recycle();shown=null;}super.onDestroy();}
}
